import React, { ElementType, forwardRef, ReactElement } from 'react';
import styled, { CSSObject } from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import Typography from '@dynatrace/strato-design-tokens/typography';
import { ChevronRightSmallIcon } from '@dynatrace/strato-icons';

import type { CSSFocusStylesObject } from '../../core/hooks/useFocusRing.js';
import { useFocusRing } from '../../core/hooks/useFocusRing.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { PolymorphicComponentProps } from '../../core/types/polymorph.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { Link } from '../../typography/Link.js';

//#region Typings
export interface BreadcrumbsItemOwnProps
  extends WithChildren,
    StylingProps,
    DataTestId {
  /**
   * Whether the breadcrumb item is disabled.
   * If `true`, it prevents the user from interacting with the item and the item
   * being focused.
   */
  disabled?: boolean;
  /**
   * The url the breadcrumb links to.
   */
  href?: string;
}

export type BreadcrumbsItemProps<E extends ElementType> =
  PolymorphicComponentProps<E, BreadcrumbsItemOwnProps>;
// #endregion

//#region Styled Components
const StyledChevronRightSmall = /* @__PURE__ */ styled(ChevronRightSmallIcon)({
  minWidth: Spacings.Size20,
  minHeight: Spacings.Size20,
  color: Colors.Icon.Neutral.Subdued,
});

const StyledListElement = /* @__PURE__ */ styled('li')<{
  $isLastVisible?: boolean;
}>(({ $isLastVisible }) => ({
  display: 'flex',
  gap: Spacings.Size2,
  paddingRight: Spacings.Size2,
  overflow: $isLastVisible ? 'hidden' : 'visible',
  whiteSpace: 'nowrap',
}));

const StyledBreadcrumbsItem = /* @__PURE__ */ styled(Link)<{
  disabled: boolean;
  $isLast?: boolean;
  $isFocusVisible?: boolean;
  $focusStyle?: CSSFocusStylesObject;
}>(({ disabled, $isLast, $focusStyle }) => {
  const lastItemStyles = {
    overflow: 'hidden',
    textOverflow: 'ellipsis',
  };

  const disabledStyles = {
    cursor: 'default',
    color: Colors.Text.Neutral.Default,
    textDecoration: 'none',
    fontWeight: Typography.Text.Base.Emphasized.Weight,
    pointerEvents: 'none',
  };

  return {
    cursor: 'pointer',
    padding: 0,
    background: 'none',
    border: 'none',
    color: Colors.Text.Primary.Default,
    fontWeight: Typography.Text.Base.Emphasized.Weight,
    fontSize: Typography.Text.Base.Emphasized.Size,
    lineHeight: Typography.Text.Base.Emphasized.LineHeight,
    textDecoration: 'underline',

    ...$focusStyle,
    ...($isLast && lastItemStyles),
    ...(disabled && disabledStyles),
  } as CSSObject;
});
// #endregion

/**
 * The component that is used for the individual Breadcrumb items.
 */
export const Item: <E extends ElementType = 'a'>(
  props: BreadcrumbsItemProps<E>,
) => ReactElement | null = /* @__PURE__ */ forwardRef(
  <E extends ElementType>(
    props: BreadcrumbsItemProps<E>,
    forwardedRef: typeof props.ref,
  ) => {
    const {
      children,
      disabled = false,
      href,
      isLast,
      isLastVisible,
      isCollapsed,
      className: consumerClassName,
      style: consumerStyle,
      'data-id': dataId,
      'data-testid': dataTestId,
      ...remainingProps
    }: BreadcrumbsItemProps<E> = props;
    const { focusStyles, focusProps, isFocusVisible } = useFocusRing({
      isMinimal: true,
      variant: remainingProps.menuTrigger ? 'neutral' : 'primary',
    });

    return (
      <StyledListElement
        className={consumerClassName}
        style={consumerStyle}
        data-id={dataId}
        data-testid={dataTestId}
        $isLastVisible={isLastVisible}
      >
        <StyledBreadcrumbsItem
          ref={forwardedRef}
          href={href}
          disabled={disabled}
          aria-disabled={disabled}
          aria-current={isLast && 'page'}
          $isFocusVisible={isFocusVisible}
          $isLast={isLast}
          {...remainingProps}
          $focusStyle={focusStyles}
          {...focusProps}
          tabIndex={!disabled ? 0 : -1}
        >
          {children}
        </StyledBreadcrumbsItem>

        {!isCollapsed && !isLast && <StyledChevronRightSmall />}
      </StyledListElement>
    );
  },
);

(Item as typeof Item & { displayName: string }).displayName = 'Breadcrumb.Item';
